### LazyColumn and LazyRow (RecyclerView)

```kotlin
@Composable
fun UserList(users: List<User>) {
    LazyColumn(
        contentPadding = PaddingValues(16.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        items(users) { user ->
            UserCard(user)
        }

        // With keys for better performance
        items(
            items = users,
            key = { it.id }
        ) { user ->
            UserCard(user)
        }
    }
}

// Grid layout
@Composable
fun PhotoGrid(photos: List<Photo>) {
    LazyVerticalGrid(
        columns = GridCells.Fixed(3),
        contentPadding = PaddingValues(8.dp),
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        items(photos) { photo ->
            PhotoItem(photo)
        }
    }
}
```

## State Management

### remember and mutableStateOf

```kotlin
@Composable
fun Counter() {
    // State survives recomposition
    var count by remember { mutableStateOf(0) }

    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        Text("Count: $count", style = MaterialTheme.typography.headlineMedium)
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(onClick = { count-- }) { Text("-") }
            Button(onClick = { count++ }) { Text("+") }
        }
    }
}
```

### State Hoisting

```kotlin
// Stateless composable - receives state and events
@Composable
fun CounterDisplay(
    count: Int,
    onIncrement: () -> Unit,
    onDecrement: () -> Unit
) {
    Column {
        Text("Count: $count")
        Row {
            Button(onClick = onDecrement) { Text("-") }
            Button(onClick = onIncrement) { Text("+") }
        }
    }
}

// Stateful composable - manages state
@Composable
fun CounterScreen() {
    var count by remember { mutableStateOf(0) }

    CounterDisplay(
        count = count,
        onIncrement = { count++ },
        onDecrement = { count-- }
    )
}
```

### rememberSaveable

```kotlin
@Composable
fun SearchBar() {
    // Survives configuration changes (rotation)
    var query by rememberSaveable { mutableStateOf("") }

    TextField(
        value = query,
        onValueChange = { query = it },
        placeholder = { Text("Search...") },
        modifier = Modifier.fillMaxWidth()
    )
}
```

### ViewModel Integration

```kotlin
class MainViewModel : ViewModel() {
    private val _uiState = MutableStateFlow(UiState())
    val uiState: StateFlow<UiState> = _uiState.asStateFlow()

    fun onEvent(event: UiEvent) {
        when (event) {
            is UiEvent.Search -> search(event.query)
            is UiEvent.Refresh -> refresh()
        }
    }

    private fun search(query: String) {
        viewModelScope.launch {
            _uiState.update { it.copy(isLoading = true) }
            val results = repository.search(query)
            _uiState.update { it.copy(isLoading = false, results = results) }
        }
    }
}

@Composable
fun MainScreen(viewModel: MainViewModel = viewModel()) {
    val uiState by viewModel.uiState.collectAsState()

    MainContent(
        uiState = uiState,
        onSearch = { viewModel.onEvent(UiEvent.Search(it)) },
        onRefresh = { viewModel.onEvent(UiEvent.Refresh) }
    )
}
```

## Material Design 3

### Theming

```kotlin
// Theme.kt
private val DarkColorScheme = darkColorScheme(
    primary = Purple80,
    secondary = PurpleGrey80,
    tertiary = Pink80
)

private val LightColorScheme = lightColorScheme(
    primary = Purple40,
    secondary = PurpleGrey40,
    tertiary = Pink40
)

@Composable
fun MyAppTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    content: @Composable () -> Unit
) {
    val colorScheme = if (darkTheme) DarkColorScheme else LightColorScheme

    MaterialTheme(
        colorScheme = colorScheme,
        typography = Typography,
        content = content
    )
}

// Usage
@Composable
fun App() {
    MyAppTheme {
        Surface(
            modifier = Modifier.fillMaxSize(),
            color = MaterialTheme.colorScheme.background
        ) {
            MainScreen()
        }
    }
}
```

### Material Components

```kotlin
@Composable
fun MaterialShowcase() {
    Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
        // Buttons
        Button(onClick = { }) { Text("Filled Button") }
        OutlinedButton(onClick = { }) { Text("Outlined") }
        TextButton(onClick = { }) { Text("Text Button") }
        FilledTonalButton(onClick = { }) { Text("Tonal") }

        // TextField
        var text by remember { mutableStateOf("") }
        OutlinedTextField(
            value = text,
            onValueChange = { text = it },
            label = { Text("Email") },
            leadingIcon = { Icon(Icons.Default.Email, null) }
        )

        // Card
        Card(
            modifier = Modifier.fillMaxWidth(),
            elevation = CardDefaults.cardElevation(4.dp)
        ) {
            Column(modifier = Modifier.padding(16.dp)) {
                Text("Card Title", style = MaterialTheme.typography.titleMedium)
                Text("Card content goes here")
            }
        }

        // Checkbox
        var checked by remember { mutableStateOf(false) }
        Row(verticalAlignment = Alignment.CenterVertically) {
            Checkbox(checked = checked, onCheckedChange = { checked = it })
            Text("Accept terms")
        }

        // Switch
        var switchOn by remember { mutableStateOf(false) }
        Switch(checked = switchOn, onCheckedChange = { switchOn = it })
    }
}
```

## Navigation

```kotlin
// Setup navigation
@Composable
fun AppNavigation() {
    val navController = rememberNavController()

    NavHost(
        navController = navController,
        startDestination = "home"
    ) {
        composable("home") {
            HomeScreen(
                onNavigateToDetail = { id ->
                    navController.navigate("detail/$id")
                }
            )
        }
        composable(
            route = "detail/{id}",
            arguments = listOf(navArgument("id") { type = NavType.StringType })
        ) { backStackEntry ->
            val id = backStackEntry.arguments?.getString("id")
            DetailScreen(
                id = id ?: "",
                onBack = { navController.popBackStack() }
            )
        }
    }
}
```

## Animations

```kotlin
@Composable
fun AnimatedVisibilityExample() {
    var visible by remember { mutableStateOf(true) }

    Column {
        Button(onClick = { visible = !visible }) {
            Text(if (visible) "Hide" else "Show")
        }

        AnimatedVisibility(
            visible = visible,
            enter = fadeIn() + slideInVertically(),
            exit = fadeOut() + slideOutVertically()
        ) {
            Card(modifier = Modifier.fillMaxWidth()) {
                Text("Animated Content", modifier = Modifier.padding(16.dp))
            }
        }
    }
}

@Composable
fun AnimatedContentExample() {
    var count by remember { mutableStateOf(0) }

    Column {
        AnimatedContent(
            targetState = count,
            transitionSpec = {
                slideInVertically { it } + fadeIn() togetherWith
                    slideOutVertically { -it } + fadeOut()
            }
        ) { targetCount ->
            Text(
                text = "$targetCount",
                style = MaterialTheme.typography.displayLarge
            )
        }
        Button(onClick = { count++ }) { Text("Increment") }
    }
}
```

## Side Effects

```kotlin
@Composable
fun SideEffectsExample() {
    // Run once when composable enters composition
    LaunchedEffect(Unit) {
        // Coroutine scope
        delay(1000)
        // Do something
    }

    // Run when key changes
    LaunchedEffect(key1 = userId) {
        loadUserData(userId)
    }

    // Access coroutine scope
    val scope = rememberCoroutineScope()
    Button(onClick = {
        scope.launch {
            // Async operation
        }
    }) { Text("Load") }

    // Cleanup on disposal
    DisposableEffect(Unit) {
        val listener = addListener()
        onDispose {
            removeListener(listener)
        }
    }
}
```

## Best Practices

### 1. Keep Composables Small

```kotlin
// Bad - too much in one composable
@Composable
fun BigScreen() { /* 200 lines */ }

// Good - break into smaller pieces
@Composable
fun ProfileScreen() {
    Column {
        ProfileHeader()
        ProfileStats()
        ProfileActions()
    }
}
```

### 2. Use State Hoisting

```kotlin
// Stateless - easy to test and reuse
@Composable
fun EmailField(
    value: String,
    onValueChange: (String) -> Unit,
    isError: Boolean = false
) {
    OutlinedTextField(
        value = value,
        onValueChange = onValueChange,
        isError = isError,
        label = { Text("Email") }
    )
}
```

### 3. Use remember Wisely

```kotlin
// Remember expensive calculations
val sortedList = remember(items) {
    items.sortedBy { it.name }
}

// Remember lambda references
val onClick = remember { { doSomething() } }
```

### 4. Preview Your Composables

```kotlin
@Preview(showBackground = true)
@Preview(uiMode = Configuration.UI_MODE_NIGHT_YES)
@Composable
fun ProfileCardPreview() {
    MyAppTheme {
        ProfileCard(
            user = User("John Doe", "@johndoe")
        )
    }
}
```

## Summary

1. ✅ Use Composable functions for UI
2. ✅ Manage state with remember and ViewModel
3. ✅ Hoist state for reusable components
4. ✅ Apply Material Design 3 theming
5. ✅ Use Navigation Compose
6. ✅ Add animations for polish
7. ✅ Preview composables during development

## Conclusion

Jetpack Compose revolutionizes Android UI development. Start with basic composables, learn state management, then build complex UIs with confidence.

**Key Takeaways:**
1. Declarative UI is easier to reason about
2. State hoisting enables reusable components
3. Material 3 provides modern design
4. Navigation Compose handles screen transitions
5. Animations make UIs feel polished

Happy composing!
